from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import ForceSensor, Motor
from pybricks.robotics import DriveBase
from pybricks.tools import multitask, run_task, wait

# Set up.
prime_hub = PrimeHub()
back_motor = Motor(Port.A, Direction.CLOCKWISE)
Left_wheel = Motor(Port.B, Direction.COUNTERCLOCKWISE)
front_motor = Motor(Port.D, Direction.CLOCKWISE)
right_wheel = Motor(Port.F, Direction.CLOCKWISE)
drive_base = DriveBase(Left_wheel, right_wheel, 62, 187)
force_sensor = ForceSensor(Port.E)

async def main1():
    drive_base.use_gyro(True)
    drive_base.settings(straight_speed=1000)
    await drive_base.straight(200)
    await drive_base.turn(90)
    await drive_base.straight(60)
    await drive_base.turn(-45)
    await front_motor.run_angle(400, 35)
    await drive_base.straight(170)
    await front_motor.run_angle(500, 40)
    await drive_base.straight(-50)
    await front_motor.run_angle(500, 22)
    await drive_base.straight(-400)

async def main2():
    if await force_sensor.force():
        drive_base.brake()
        await prime_hub.speaker.beep(500, 30)
        while True:
            await wait(1000)
    else:
        pass


async def main():
    await multitask(main1(), main2())

run_task(main())